insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('seguridad-percibida-como-se-sienten-los-vecinos-en-sus-espacios','sociedad',array['ciudades']::text[],'Seguridad percibida: cómo se sienten los vecinos en sus espacios','Averigua cómo se sienten las personas en los espacios de su barrio, en qué lugares y horarios se sienten más o menos seguras y qué factores influyen, sin buscar datos delictivos ni señalar personas.','Investigación','3 a 4 semanas',24,array['Seguridad percibida','Espacios públicos']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion diseno de encuestas. mapeo. analisis cualitativo. redaccion. un formulario en linea. un editor de mapas. hoja de calculo.',$a59sld${"id": "seguridad-percibida-como-se-sienten-los-vecinos-en-sus-espacios", "area": "sociedad", "areas2": ["ciudades"], "titulo": "Seguridad percibida: cómo se sienten los vecinos en sus espacios", "resumen": "Averigua cómo se sienten las personas en los espacios de su barrio, en qué lugares y horarios se sienten más o menos seguras y qué factores influyen, sin buscar datos delictivos ni señalar personas.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Seguridad percibida", "Espacios públicos"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["La seguridad no es solo una cifra: también es una sensación que cambia según el lugar, la hora, la iluminación, el movimiento de gente y las experiencias previas. Esa percepción afecta si las personas salen, se reúnen o usan un parque.", "Conocerla ayuda a pensar mejoras del espacio y de la convivencia."], "desarrollar": ["Con una encuesta anónima y voluntaria, pregunta a vecinos cómo se sienten en cinco o seis lugares de su zona en distintos horarios y qué factores influyen, como iluminación, limpieza o presencia de gente. Complementa con una observación diurna y nocturna acompañada, de forma segura.", "Elabora un mapa de percepciones con colores, identifica los factores asociados a sentirse más seguro y propón mejoras simples, como iluminación, mantenimiento o actividades que generen movimiento."], "ampliaciones": [{"titulo": "Diferencias por grupos", "aporta": "compara percepciones entre mujeres, hombres, jóvenes y mayores."}, {"titulo": "Cambios en el tiempo", "aporta": "repite el estudio meses después."}, {"titulo": "Cuidado entre vecinos", "aporta": "propón acciones de cuidado colectivo no punitivas."}], "objetivos": ["Diseñar una encuesta de percepción.", "Mapear lugares y horarios.", "Identificar factores.", "Proponer mejoras."], "habilidades": ["Diseño de encuestas.", "Mapeo.", "Análisis cualitativo.", "Redacción."], "herramientas": ["Un formulario en línea.", "Un editor de mapas.", "Hoja de cálculo."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Evita recoger o publicar información sobre delitos o personas: trata solo percepciones y condiciones del espacio.", "Haz observaciones de forma segura, acompañada y sin exponerte."], "otroSector": "El mismo estudio sirve para evaluar la percepción de seguridad en un campus o en un centro de trabajo."}$a59sld$::jsonb,69),
('primer-empleo-expectativas-y-realidad-de-los-jovenes','sociedad',array['negocios']::text[],'Primer empleo: expectativas y realidad de los jóvenes','Compara lo que los jóvenes esperan de su primer empleo con lo que realmente encuentran, con una encuesta anónima, y descubre en qué coinciden y qué sorpresas aparecen.','Investigación','3 a 4 semanas',24,array['Primer empleo','Jóvenes']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion diseno de encuestas. analisis de datos. comunicacion. redaccion. un formulario en linea. hoja de calculo. un editor de graficos.',$a60sld${"id": "primer-empleo-expectativas-y-realidad-de-los-jovenes", "area": "sociedad", "areas2": ["negocios"], "titulo": "Primer empleo: expectativas y realidad de los jóvenes", "resumen": "Compara lo que los jóvenes esperan de su primer empleo con lo que realmente encuentran, con una encuesta anónima, y descubre en qué coinciden y qué sorpresas aparecen.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Primer empleo", "Jóvenes"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Los jóvenes suelen llegar al primer empleo con ideas sobre horarios, pago, trato y aprendizaje que luego chocan con la realidad. Esas diferencias generan frustración o renuncias tempranas, y rara vez se conversan antes.", "Conocerlas ayuda a prepararse mejor y a que las organizaciones reciban mejor a quienes empiezan."], "desarrollar": ["Diseña dos cuestionarios anónimos: uno para estudiantes que aún no trabajan sobre qué esperan, y otro para jóvenes con su primer empleo sobre qué encontraron. Aplícalos a 20 o más personas de cada grupo con consentimiento.", "Compara expectativas con experiencias en temas como sueldo, horario, aprendizaje, trato y estabilidad, y resume en cinco hallazgos y diez consejos prácticos para quienes buscan su primer empleo."], "ampliaciones": [{"titulo": "Prácticas y empleo", "aporta": "compara experiencias en prácticas y en empleos formales."}, {"titulo": "Cómo prepararse", "aporta": "arma una lista de preguntas para hacer antes de aceptar."}, {"titulo": "Voz de las organizaciones", "aporta": "recoge qué esperan los empleadores de un primer empleo."}], "objetivos": ["Diseñar dos cuestionarios.", "Comparar expectativas y realidad.", "Resumir hallazgos.", "Elaborar consejos."], "habilidades": ["Diseño de encuestas.", "Análisis de datos.", "Comunicación.", "Redacción."], "herramientas": ["Un formulario en línea.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "No nombres empresas ni personas en tu análisis y no recojas datos que identifiquen a los participantes."], "otroSector": "El mismo estudio sirve para entender expectativas de nuevos trabajadores en cualquier sector."}$a60sld$::jsonb,70),
('cuanto-vale-el-trabajo-voluntario-y-comunitario-que-no-se-paga','sociedad',array['negocios']::text[],'¿Cuánto vale el trabajo voluntario y comunitario que no se paga?','Estima con métodos simples cuánto valdría en dinero y en beneficios el trabajo voluntario y comunitario, como ollas comunes, cuidado de niños o limpieza de espacios, y discute qué se gana y qué no se puede medir así.','Análisis','3 a 4 semanas',24,array['Trabajo voluntario','Valoración']::text[],array['investigar']::text[],'publicos',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion estimacion. calculo en hoja de calculo. pensamiento critico. redaccion. hoja de calculo. estadisticas de salarios. un editor de documentos.',$a61sld${"id": "cuanto-vale-el-trabajo-voluntario-y-comunitario-que-no-se-paga", "area": "sociedad", "areas2": ["negocios"], "titulo": "¿Cuánto vale el trabajo voluntario y comunitario que no se paga?", "resumen": "Estima con métodos simples cuánto valdría en dinero y en beneficios el trabajo voluntario y comunitario, como ollas comunes, cuidado de niños o limpieza de espacios, y discute qué se gana y qué no se puede medir así.", "tipo": "Análisis", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Trabajo voluntario", "Valoración"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Mucho trabajo que sostiene a las comunidades no se paga y por eso no aparece en las estadísticas ni se reconoce. Cocinar en una olla común, organizar una fiesta o cuidar un espacio compartido tienen un valor real.", "Estimarlo permite visibilizarlo sin reducirlo solo a dinero."], "desarrollar": ["Elige una actividad comunitaria o de voluntariado de ejemplo y estima las horas de trabajo y el costo que tendría contratar ese servicio, usando salarios de referencia de fuentes públicas. Presenta el cálculo paso a paso en una hoja de cálculo.", "Reflexiona sobre qué valor no se mide con dinero, como la confianza, el aprendizaje y los vínculos, y redacta un breve informe con la estimación, sus supuestos y sus límites."], "ampliaciones": [{"titulo": "Comparar actividades", "aporta": "estima el valor de tres actividades distintas."}, {"titulo": "Quién aporta más", "aporta": "analiza cómo se distribuye este trabajo por género y edad."}, {"titulo": "Reconocimiento", "aporta": "propón formas no monetarias de reconocer el aporte."}], "objetivos": ["Estimar horas y valor.", "Documentar supuestos.", "Reconocer lo que no se mide.", "Redactar un informe."], "habilidades": ["Estimación.", "Cálculo en hoja de cálculo.", "Pensamiento crítico.", "Redacción."], "herramientas": ["Hoja de cálculo.", "Estadísticas de salarios.", "Un editor de documentos."], "lineamientos": ["Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Explica que la estimación es aproximada y que su objetivo es visibilizar el trabajo, no ponerle precio a las personas."], "otroSector": "El mismo método sirve para estimar el valor del trabajo doméstico o de cuidado."}$a61sld$::jsonb,71),
('juntas-pandero-y-ollas-comunes-formas-de-ahorro-y-ayuda-colectiv','sociedad',array['negocios']::text[],'Juntas, pandero y ollas comunes: formas de ahorro y ayuda colectiva','Documenta cómo funcionan las juntas, los panderos y las ollas comunes en una comunidad, qué reglas tienen, qué riesgos y qué valor social aportan, a partir de conversaciones voluntarias y fuentes públicas.','Investigación','3 a 4 semanas',24,array['Economía solidaria','Ahorro colectivo']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion entrevistas. analisis cualitativo. pensamiento critico. redaccion. una guia de conversacion. un editor de documentos. fuentes publicas.',$a62sld${"id": "juntas-pandero-y-ollas-comunes-formas-de-ahorro-y-ayuda-colectiv", "area": "sociedad", "areas2": ["negocios"], "titulo": "Juntas, pandero y ollas comunes: formas de ahorro y ayuda colectiva", "resumen": "Documenta cómo funcionan las juntas, los panderos y las ollas comunes en una comunidad, qué reglas tienen, qué riesgos y qué valor social aportan, a partir de conversaciones voluntarias y fuentes públicas.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Economía solidaria", "Ahorro colectivo"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Muchas familias recurren a formas colectivas de ahorro y ayuda, como juntas, panderos o ollas comunes, que funcionan por confianza y reglas propias, sin bancos ni contratos. Son importantes en la vida diaria, pero se conocen poco y se registran menos.", "Documentarlas permite entender su valor, sus riesgos y cómo hacerlas más seguras."], "desarrollar": ["Con fuentes públicas y conversaciones voluntarias y anónimas, describe cómo funciona cada forma: quiénes participan, cómo se organiza, qué reglas existen, qué pasa si alguien no cumple y qué beneficios obtienen. No preguntes montos ni datos personales.", "Analiza los factores que las hacen funcionar, como confianza y reglas claras, y los riesgos, como incumplimientos. Elabora una guía con buenas prácticas para participar de forma segura."], "ampliaciones": [{"titulo": "Comparar con ahorro formal", "aporta": "compara con cuentas de ahorro y cooperativas."}, {"titulo": "Registro y transparencia", "aporta": "propón formas simples de llevar cuentas claras."}, {"titulo": "Origen y cambios", "aporta": "investiga cómo han cambiado en el tiempo."}], "objetivos": ["Describir formas de ahorro y ayuda colectiva.", "Analizar reglas y riesgos.", "Reconocer su valor social.", "Elaborar una guía."], "habilidades": ["Entrevistas.", "Análisis cualitativo.", "Pensamiento crítico.", "Redacción."], "herramientas": ["Una guía de conversación.", "Un editor de documentos.", "Fuentes públicas."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "No pidas ni registres montos ni datos financieros de personas: describe las reglas en general.", "Aclara que es información educativa, no asesoría financiera."], "otroSector": "El mismo estudio sirve para entender otras formas de economía solidaria o de crédito comunitario."}$a62sld$::jsonb,72),
('como-se-crea-una-asociacion-u-ong-en-el-peru-pasos-costos-y-requ','sociedad',array['derecho','negocios']::text[],'Cómo se crea una asociación u ONG en el Perú: pasos, costos y requisitos','Describe, con fuentes oficiales, los pasos para constituir una asociación sin fines de lucro u ONG en el Perú, qué documentos se piden, cuánto suele costar y demorar y qué obligaciones vienen después.','Guía','3 a 4 semanas',24,array['Asociaciones','ONG','Formalización']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho trabajo social administracion sociologia contabilidad ciencias politicas comunicaciones ingenieria industrial lectura de normas. diagramacion de procesos. estimacion de costos. redaccion. portales oficiales. un editor de diagramas. hoja de calculo.',$a63sld${"id": "como-se-crea-una-asociacion-u-ong-en-el-peru-pasos-costos-y-requ", "area": "sociedad", "areas2": ["derecho", "negocios"], "titulo": "Cómo se crea una asociación u ONG en el Perú: pasos, costos y requisitos", "resumen": "Describe, con fuentes oficiales, los pasos para constituir una asociación sin fines de lucro u ONG en el Perú, qué documentos se piden, cuánto suele costar y demorar y qué obligaciones vienen después.", "tipo": "Guía", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Asociaciones", "ONG", "Formalización"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Trabajo Social", "Administración", "Sociología", "Contabilidad", "Ciencias Políticas", "Comunicaciones", "Ingeniería Industrial"], "problema": ["Muchos grupos de voluntarios quieren formalizarse, pero no saben por dónde empezar: qué tipo de organización conviene, qué se firma, dónde se inscribe y qué obligaciones tendrá. La información está dispersa y parece complicada.", "Una guía ordenada con fuentes oficiales ayuda a entender el camino antes de decidir."], "desarrollar": ["Con portales oficiales y fuentes confiables, describe las etapas, como definir el propósito, redactar el estatuto, elegir una directiva, el acta de constitución, la inscripción registral y los trámites tributarios. Indica qué documentos se necesitan y qué instituciones intervienen.", "Arma un diagrama de flujo con costos y plazos aproximados con fecha de consulta, y una lista de obligaciones posteriores, como libros, reportes y rendición de cuentas. Pruébala simulando la constitución de una asociación ficticia."], "ampliaciones": [{"titulo": "Comparar figuras", "aporta": "compara asociación, fundación y comité."}, {"titulo": "Estatuto modelo", "aporta": "redacta un estatuto de ejemplo explicado."}, {"titulo": "Costos del primer año", "aporta": "estima el presupuesto de formalización y mantenimiento."}], "objetivos": ["Reunir requisitos oficiales.", "Dibujar el proceso.", "Estimar costos y plazos.", "Simular una constitución ficticia."], "habilidades": ["Lectura de normas.", "Diagramación de procesos.", "Estimación de costos.", "Redacción."], "herramientas": ["Portales oficiales.", "Un editor de diagramas.", "Hoja de cálculo."], "lineamientos": ["Es información general y educativa, no asesoría legal ni contable: antes de constituir una organización conviene verificar los requisitos vigentes en fuentes oficiales y consultar a un especialista.", "Cita la fecha de consulta de cada requisito y costo, porque cambian con frecuencia.", "No presentes una organización real: usa un ejemplo ficticio."], "otroSector": "La misma guía sirve para entender la formalización de pequeños negocios o de colectivos culturales."}$a63sld$::jsonb,73),
('del-grupo-de-amigos-a-la-organizacion-cuando-conviene-formalizar','sociedad',array['negocios']::text[],'Del grupo de amigos a la organización: cuándo conviene formalizarse y cuándo no','Analiza qué cambia cuando un grupo informal se vuelve una organización formal, con qué ventajas, obligaciones y riesgos, y cuándo conviene dar el paso o seguir como grupo.','Análisis','3 semanas',22,array['Formalización','Organizaciones']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion analisis comparativo. pensamiento estrategico. lectura de fuentes. redaccion. fuentes oficiales. hoja de calculo. un editor de documentos.',$a64sld${"id": "del-grupo-de-amigos-a-la-organizacion-cuando-conviene-formalizar", "area": "sociedad", "areas2": ["negocios"], "titulo": "Del grupo de amigos a la organización: cuándo conviene formalizarse y cuándo no", "resumen": "Analiza qué cambia cuando un grupo informal se vuelve una organización formal, con qué ventajas, obligaciones y riesgos, y cuándo conviene dar el paso o seguir como grupo.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Formalización", "Organizaciones"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Muchos grupos nacen entre amigos y funcionan bien sin papeles. Pero llega un momento en que quieren recibir donaciones, pedir fondos o abrir una cuenta y se preguntan si deben formalizarse. A veces lo hacen demasiado pronto y se llenan de trámites; otras tarde y pierden oportunidades.", "Un análisis de pros y contras ayuda a decidir con criterio."], "desarrollar": ["Elabora una tabla de ventajas y obligaciones de una organización formal frente a un grupo informal, con fuentes confiables: acceso a fondos, responsabilidad, trámites, costos, imagen y continuidad. Añade señales de que ha llegado el momento de formalizarse.", "Aplica el análisis a tres grupos ficticios con situaciones distintas, como un voluntariado escolar, una olla común y un colectivo cultural, y recomienda una ruta para cada uno."], "ampliaciones": [{"titulo": "Etapas de crecimiento", "aporta": "dibuja las etapas de un grupo desde lo informal hasta lo formal."}, {"titulo": "Alternativas intermedias", "aporta": "analiza formas de trabajar con una organización ya formada."}, {"titulo": "Lista de verificación", "aporta": "crea una lista para decidir si es el momento."}], "objetivos": ["Comparar grupo informal y organización formal.", "Identificar señales para formalizarse.", "Aplicar a casos ficticios.", "Recomendar rutas."], "habilidades": ["Análisis comparativo.", "Pensamiento estratégico.", "Lectura de fuentes.", "Redacción."], "herramientas": ["Fuentes oficiales.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Es información general y educativa, no asesoría legal ni contable: antes de constituir una organización conviene verificar los requisitos vigentes en fuentes oficiales y consultar a un especialista.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Usa grupos ficticios y presenta recomendaciones generales, no decisiones para casos reales."], "otroSector": "El mismo análisis sirve para decidir cuándo formalizar un emprendimiento o un club."}$a64sld$::jsonb,74),
('como-financia-una-organizacion-social-sus-actividades-donaciones','sociedad',array['negocios','derecho']::text[],'Cómo financia una organización social sus actividades: donaciones, fondos concursables y rendición de cuentas','Explica de dónde obtiene dinero una organización social, como donaciones, cuotas, fondos concursables o venta de servicios, y cómo debe informar su uso para mantener la confianza.','Análisis','4 semanas',26,array['Financiamiento','Rendición de cuentas']::text[],array['investigar','crear']::text[],'publicos',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion presupuestos basicos. lectura de bases de fondos. transparencia. redaccion. hoja de calculo. portales de fondos publicos. un editor de documentos.',$a65sld${"id": "como-financia-una-organizacion-social-sus-actividades-donaciones", "area": "sociedad", "areas2": ["negocios", "derecho"], "titulo": "Cómo financia una organización social sus actividades: donaciones, fondos concursables y rendición de cuentas", "resumen": "Explica de dónde obtiene dinero una organización social, como donaciones, cuotas, fondos concursables o venta de servicios, y cómo debe informar su uso para mantener la confianza.", "tipo": "Análisis", "tiempo": "4 semanas", "horas": 26, "etiquetas": ["Financiamiento", "Rendición de cuentas"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Muchas buenas ideas sociales se detienen por falta de dinero, y otras pierden la confianza de la gente por no rendir cuentas con claridad. Entender las fuentes de financiamiento y sus condiciones es clave para sostener una organización.", "También lo es saber informar con transparencia en qué se gasta."], "desarrollar": ["Con fuentes públicas y ejemplos de reportes de organizaciones, describe las principales fuentes de financiamiento, qué suelen exigir los fondos concursables y cómo es una rendición de cuentas simple. Reúne dos a tres ejemplos de informes de organizaciones reales sin evaluarlas.", "Diseña una plantilla de presupuesto y de informe de rendición de cuentas de una página y aplícala a una organización ficticia con ingresos, gastos y resultados. Elabora una lista de buenas prácticas de transparencia."], "ampliaciones": [{"titulo": "Presupuesto anual", "aporta": "arma un presupuesto de un año para una organización ficticia."}, {"titulo": "Redactar una propuesta", "aporta": "prepara el esquema de una propuesta a un fondo."}, {"titulo": "Riesgos", "aporta": "analiza dependencia de una sola fuente de financiamiento."}], "objetivos": ["Describir fuentes de financiamiento.", "Entender requisitos de fondos.", "Diseñar plantillas de presupuesto e informe.", "Aplicarlas a un caso."], "habilidades": ["Presupuestos básicos.", "Lectura de bases de fondos.", "Transparencia.", "Redacción."], "herramientas": ["Hoja de cálculo.", "Portales de fondos públicos.", "Un editor de documentos."], "lineamientos": ["Es información general y educativa, no asesoría legal ni contable: antes de constituir una organización conviene verificar los requisitos vigentes en fuentes oficiales y consultar a un especialista.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "No evalúes ni cuestiones a organizaciones reales: usa sus informes solo como ejemplos descriptivos."], "otroSector": "La misma plantilla sirve para rendir cuentas en proyectos escolares, clubes o emprendimientos."}$a65sld$::jsonb,75),
('como-saber-si-una-ong-o-una-colecta-es-confiable-antes-de-donar','sociedad',array['derecho','tecnologia']::text[],'¿Cómo saber si una ONG o una colecta es confiable antes de donar o ser voluntario?','Elabora una lista de verificación para comprobar si una organización o una colecta es confiable antes de donar o ser voluntario, con señales de alerta y formas de verificar en fuentes oficiales.','Guía','3 semanas',20,array['Donaciones','Confianza']::text[],array['crear','resolver']::text[],'publicos',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion pensamiento critico. verificacion de fuentes. redaccion. diseno de guias. portales oficiales. un editor de documentos. casos ficticios.',$a66sld${"id": "como-saber-si-una-ong-o-una-colecta-es-confiable-antes-de-donar", "area": "sociedad", "areas2": ["derecho", "tecnologia"], "titulo": "¿Cómo saber si una ONG o una colecta es confiable antes de donar o ser voluntario?", "resumen": "Elabora una lista de verificación para comprobar si una organización o una colecta es confiable antes de donar o ser voluntario, con señales de alerta y formas de verificar en fuentes oficiales.", "tipo": "Guía", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Donaciones", "Confianza"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Las redes y la calle están llenas de pedidos de ayuda, y es difícil saber cuáles son reales. Algunas colectas no llegan a destino y otras se usan para estafas. Esto daña la confianza y perjudica a las organizaciones honestas.", "Una forma ordenada de verificar protege a quien dona y a quien necesita ayuda."], "desarrollar": ["Con fuentes oficiales y alertas públicas, define criterios de verificación como inscripción formal, información de contacto, transparencia de cuentas, trayectoria y claridad del pedido. Elabora una lista de diez preguntas y señales de alerta.", "Aplícala a cinco ejemplos ficticios de colectas, unas confiables y otras dudosas, y explica qué señales sirvieron. Redacta una guía de una página con qué hacer si se sospecha de una estafa."], "ampliaciones": [{"titulo": "Verificar en línea", "aporta": "enseña a buscar registros y reseñas con criterio."}, {"titulo": "Donar en especie", "aporta": "agrega consejos para donaciones de ropa o alimentos."}, {"titulo": "Versión corta", "aporta": "crea una tarjeta de cinco preguntas para compartir."}], "objetivos": ["Definir criterios de confianza.", "Elaborar una lista de verificación.", "Aplicarla a casos.", "Redactar una guía."], "habilidades": ["Pensamiento crítico.", "Verificación de fuentes.", "Redacción.", "Diseño de guías."], "herramientas": ["Portales oficiales.", "Un editor de documentos.", "Casos ficticios."], "lineamientos": ["Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Usa casos ficticios y no señales a organizaciones reales como estafas sin pruebas.", "Aclara que la lista reduce riesgos, pero no los elimina."], "otroSector": "La misma lista sirve para verificar proveedores o campañas de financiamiento colectivo."}$a66sld$::jsonb,76),
('del-problema-al-proyecto-social-disenar-un-plan-con-objetivos-pr','sociedad',array['negocios']::text[],'Del problema al proyecto social: diseñar un plan con objetivos, presupuesto y resultados esperados','Aprende a convertir un problema social en un proyecto bien planteado, con diagnóstico, objetivos, actividades, presupuesto, indicadores y riesgos, usando un ejemplo ficticio y una plantilla reutilizable.','Plan','4 a 5 semanas',28,array['Proyectos sociales','Planificación']::text[],array['crear','resolver']::text[],'ficticios',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion diseno de proyectos. planificacion. presupuestos basicos. redaccion tecnica. un editor de documentos. hoja de calculo. un editor de diagramas.',$a67sld${"id": "del-problema-al-proyecto-social-disenar-un-plan-con-objetivos-pr", "area": "sociedad", "areas2": ["negocios"], "titulo": "Del problema al proyecto social: diseñar un plan con objetivos, presupuesto y resultados esperados", "resumen": "Aprende a convertir un problema social en un proyecto bien planteado, con diagnóstico, objetivos, actividades, presupuesto, indicadores y riesgos, usando un ejemplo ficticio y una plantilla reutilizable.", "tipo": "Plan", "tiempo": "4 a 5 semanas", "horas": 28, "etiquetas": ["Proyectos sociales", "Planificación"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Es común tener claro un problema pero no saber cómo pasar a un proyecto concreto: qué hacer primero, cuánto cuesta, quién lo hará y cómo se sabrá si funcionó. Sin ese plan, las ideas se quedan en intención.", "Una estructura simple permite ordenar el pensamiento y presentar la propuesta a otros."], "desarrollar": ["Elige un problema social de tu zona y estructura el proyecto con diagnóstico, objetivo general y específicos, actividades, cronograma, presupuesto, responsables, indicadores y riesgos. Usa una plantilla de dos a cuatro páginas.", "Revisa el proyecto con un compañero que haga de evaluador, usando una lista de criterios de claridad y factibilidad, y ajústalo. Entrega la plantilla y el ejemplo completo."], "ampliaciones": [{"titulo": "Árbol de problemas", "aporta": "construye un árbol de causas y efectos del problema."}, {"titulo": "Presupuesto", "aporta": "detalla costos y cómo se cubrirían."}, {"titulo": "Marco lógico simple", "aporta": "resume el proyecto en una matriz de objetivos e indicadores."}], "objetivos": ["Diagnosticar un problema.", "Definir objetivos e indicadores.", "Elaborar cronograma y presupuesto.", "Revisar con un evaluador."], "habilidades": ["Diseño de proyectos.", "Planificación.", "Presupuestos básicos.", "Redacción técnica."], "herramientas": ["Un editor de documentos.", "Hoja de cálculo.", "Un editor de diagramas."], "lineamientos": ["Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Preséntalo como un ejercicio de diseño: para ejecutarlo se necesita acuerdo de la comunidad o de una organización.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar."], "otroSector": "La misma estructura sirve para proyectos de investigación, de mejora en una empresa o de emprendimiento."}$a67sld$::jsonb,77)
